"""Focused shipped Engine/Scene checks on isolated practice fixtures; no campaign traversal."""
import json,re
from playwright.sync_api import sync_playwright
from browser_support import ROOT,launch,serve_game
OUT=ROOT/'_local/reports/equipment-tactical';OUT.mkdir(parents=True,exist_ok=True)
SETUP=r'''()=>{const a=HonroApp,C=HONRO_CORE;a.frame=()=>{};a.profile.settings.music=false;a.profile.settings.sound=false;a.updateAudio();window.gearArena=(skill,ids=[])=>{
 a.trainingClass=C.SKILLS[skill].cls;a.trainingSkill=skill;a.trainingRanks[skill]=1;a.trainingPassives={};a.launch(1,true,skill);a.done=false;a.turnNotice=null;a.dialogue=null;
 const e=a.engine,b=e.b,u=e.active;Object.assign(b,{practiceCombat:false,width:2600,height:1500,wind:0,fields:[],waters:[],drafts:[],zones:[],stakes:[],honroMarkers:[],honroSurfaceZones:[],honroLandmarks:[]});
 b.terrain=[{id:'floor',x:0,y:1100,w:2600,h:400,hp:99999,maxHp:99999,mat:'rock'}];b.units=[u];Object.assign(u,{x:400,y:1100,spawnX:400,spawnY:1100,vx:0,vy:0,airborne:false,jumping:false,acted:false,attack:1,ranks:{[C.baseSkill(u.cls)]:1,[skill]:1},loadout:[skill],equipmentIds:ids,hp:900,maxHp:1200,focus:500,maxFocus:500,cooldowns:{},angle:25});
 b.phase='aim';b.active=u.id;b.sceneVersion++;e.checkEnd=()=>false;e.random=()=>.99;a.selected=skill;a.selectedByUnit[u.id]=skill;Object.assign(a.scene,{manual:true,storyTween:null,goalFocus:null,cinematic:null,x:850,y:970,scale:.65});a.scene.arcFx.fxs=[];
 window.gearEvents=[];const event=e.onEvent;e.onEvent=ev=>{gearEvents.push(ev);event(ev);};a.updateHUD(true);
 const foe=(x,extra={})=>{const t=C.makeUnit('knight',1,x,1100,{id:'target-'+b.units.length,name:'허상',role:'dummy',hp:10000,maxHp:10000,armor:0,loadout:['LS00'],...extra});b.units.push(t);return t;};return{e,b,u,foe};
 };window.gearRender=()=>{const a=HonroApp;a.updateHUD(true);a.scene.render(a.engine,.05,'',.5,false,.05);};}'''
CASES={
 'U01-floor-bounce':r'''()=>{const{e,b,u}=gearArena('A11',['itm_se_05']);const plan=e.predict(u,HONRO_CORE.SKILLS.A11,25,.4);if(!e.fire('A11',25,.4))throw Error('fire');const p=b.projectiles[0];let n=0;while(b.projectiles.includes(p)&&!p.equipment.bounced&&n++<1400)e.stepProjectile(p,1/120);if(!p.equipment.bounced)throw Error('no natural floor bounce');for(let i=0;i<15;i++)e.stepProjectile(p,1/120);Object.assign(HonroApp.scene,{x:p.x-150,y:1010,scale:.75});gearRender();return{bounced:p.equipment.bounced,age:p.age,travel:p.equipment.travelled,previewEnds:{x:plan.x,y:plan.y}};}''',
 'U06-wall-reverse':r'''()=>{const{e,b,u,foe}=gearArena('M03',['itm_da_08']);u.x=650;b.terrain.push({id:'arc-wall',x:1050,y:760,w:35,h:340,mat:'rock',hp:99999,maxHp:99999});const t=foe(900);if(!e.fire('M03',25,.7))throw Error('fire');let n=0;while(b.projectiles.length&&n++<1200)for(const p of [...b.projectiles])e.stepProjectile(p,1/120);const event=gearEvents.find(ev=>ev.name==='skillGeometry');if(!event)throw Error('no geometry');const g=JSON.parse(event.text);if(Math.abs(g.x-g.impact.x)>1||Math.abs(g.y-g.impact.y)>1)throw Error('not terrain reverse');gearRender();return{geometry:g,targetHp:t.hp};}''',
 'U07-focused-reflection':r'''()=>{const{e,b}=gearArena('M11',['itm_da_05']);b.terrain.push({id:'wall',x:1050,y:740,w:35,h:360,mat:'rock',hp:99999,maxHp:99999});if(!e.fire('M11',0,.65))throw Error('fire');const p=b.projectiles[0];let n=0;while(b.projectiles.includes(p)&&p.bounces===0&&n++<1200)e.stepProjectile(p,1/120);for(let i=0;i<10;i++)e.stepProjectile(p,1/120);if(p.bounces!==1||b.projectiles.length!==1)throw Error('focused split');gearRender();return{bounces:p.bounces,projectiles:b.projectiles.length,damage:p.damage};}''',
 'U10-ground-moon':r'''()=>{const{e,b}=gearArena('S09',['itm_hw_08']);if(!e.fire('S09',0,.65))throw Error('fire');const p=b.projectiles[0];let n=0;while(b.projectiles.includes(p)&&p.equipment.groundLeft===undefined&&n++<1000)e.stepProjectile(p,1/120);for(let i=0;i<14;i++)e.stepProjectile(p,1/120);if(p.equipment.groundLeft===undefined)throw Error('no natural floor tracking');Object.assign(HonroApp.scene,{x:p.x-100,y:1000,scale:.8});gearRender();return{groundLeft:p.equipment.groundLeft,position:{x:p.x,y:p.y}};}''',
 'U11-visible-retreat':r'''()=>{const{e,b,u,foe}=gearArena('S01',['itm_hw_05']);foe(520);if(!e.fire('S01',0,.5))throw Error('fire');let n=0;while(!u.equipmentState?.motion&&n++<1000){for(const p of [...b.projectiles])e.stepProjectile(p,1/120);e.stepUnits(1/120);}if(!u.equipmentState?.motion)throw Error('no safe retreat');e.stepUnits(.05);Object.assign(HonroApp.scene,{x:490,y:1000,scale:.95});gearRender();return{cursor:u.equipmentState.motion.cursor,path:u.equipmentState.motion.points};}''',
 'U08-fixed-frost-zone':r'''()=>{const{e,b,u,foe}=gearArena('M02',['itm_da_06']);const t=foe(940);if(!e.fire('M02',0,.7))throw Error('fire');const p=b.projectiles[0];let n=0;while(b.projectiles.includes(p)&&p.x<900&&n++<1000)e.stepProjectile(p,1/120);if(!e.detonateIceGourd())throw Error('open');if(b.zones.length!==1||b.zones[0].damage!==0)throw Error('frost');const zone={...b.zones[0]},hp=t.hp;e.applyZones(t);if(t.hp!==hp)throw Error('zone damage');Object.assign(HonroApp.scene,{x:850,y:970,scale:.7});gearRender();return{zone,slow:HONRO_CORE.gearFrostSlow(e,t)};}''',
 'U20-return-fragment':r'''()=>{const{e,b}=gearArena('O01',['itm_so_07']);b.terrain.push({id:'wall',x:1000,y:760,w:40,h:340,mat:'rock',hp:99999,maxHp:99999});if(!e.fire('O01',0,.7))throw Error('fire');let n=0;while(!b.projectiles.some(p=>p.equipment?.returning)&&b.projectiles.length&&n++<1200)for(const p of [...b.projectiles])e.stepProjectile(p,1/120);const p=b.projectiles.find(p=>p.equipment?.returning);if(!p)throw Error('no natural terrain return');for(let i=0;i<12;i++)e.stepProjectile(p,1/120);gearRender();return{secondary:p.secondary,returning:p.equipment.returning,age:p.age,travel:p.equipment.travelled};}'''
}
rows=[];errors=[];missing=[]
with serve_game() as base,sync_playwright() as p:
 browser=launch(p);ctx=browser.new_context(viewport={'width':844,'height':390},is_mobile=True,has_touch=True);page=ctx.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.on('response',lambda r:missing.append(r.url) if r.status==404 else None)
 page.goto(base+'/HONRO.html',wait_until='domcontentloaded');page.wait_for_function('window.HonroApp');page.evaluate("async()=>await HonroOptionalRuntime.load('training')");page.evaluate(SETUP)
 for name,code in CASES.items():
  value=page.evaluate(code);page.wait_for_function("[...document.querySelectorAll('[data-skill-icon] img')].every(i=>i.complete&&i.naturalWidth>0)&&[...document.querySelectorAll('[data-portrait-state]')].every(c=>c.dataset.portraitState==='ready')");page.evaluate('gearRender()');assert all(re.fullmatch(r'\d+(?:\.\d)?(?:회)?',v) for v in page.locator('.mana-cost').all_text_contents() if v);page.screenshot(path=str(OUT/(name+'.png')));rows.append({'scene':name,'value':value});print('PASS actual mobile practice',name,flush=True)
 # UI copy is inspected in the existing isolated debug profile, never written as normal ownership.
 page.set_viewport_size({'width':390,'height':844});page.evaluate("()=>{const a=HonroApp;a.stopBattle();window.normalEquipment=JSON.stringify(a.normalProfile.equipment);a.setDebugMode(true);a.showCamp('knight');}")
 page.locator('.equipment-bag-item[data-id="itm_hw_06"]').click();assert '25%' in page.locator('.equipment-effect').inner_text();assert page.get_by_role('button',name='장비 설명 닫기',exact=True).is_visible();page.screenshot(path=str(OUT/'mobile-U12-detail.png'))
 page.get_by_role('button',name='장비 설명 닫기',exact=True).click();assert not page.locator('.equipment-detail').count();page.locator('.hero-tab[data-class="archer"]').click();page.locator('.equipment-bag-item[data-id="itm_co_20"]').click();assert '고유능력' not in page.locator('.equipment-effect').inner_text();assert not page.locator('.equipment-bag-item[data-id="itm_co_20"] .equipment-unique-seal').count();assert page.locator('.equipment-lore').inner_text();page.keyboard.press('Escape');assert not page.locator('.equipment-detail').count();page.evaluate('HonroApp.showCamp()');assert not page.locator('.equipment-detail').count();assert page.evaluate('JSON.stringify(HonroApp.normalProfile.equipment)===normalEquipment');rows.append({'scene':'mobile current copy/X/deferred26/debug isolation','value':'passed'})
 for label,size in [('landscape',{'width':844,'height':390}),('desktop',{'width':1280,'height':800})]:
  page.set_viewport_size(size);page.evaluate("HonroApp.showCamp('mage')");page.locator('.equipment-bag-item[data-id="itm_da_03"]').click();assert page.get_by_role('button',name='장비 설명 닫기',exact=True).is_visible();assert page.locator('.equipment-detail-actions').is_visible();assert '피해 +10%' in page.locator('.equipment-options').inner_text();page.screenshot(path=str(OUT/(label+'-tree-basic-detail.png')));page.get_by_role('button',name='장비 설명 닫기',exact=True).click();assert not page.locator('.equipment-detail').count();rows.append({'scene':label+' current group option/detail close','value':'passed'})
 for width in [390,1280]:
  page.set_viewport_size({'width':width,'height':844 if width==390 else 800});page.goto(base+'/game/docs/equipment/unique_candidates_20261028.html');assert page.locator('.candidate-row').count()==30;assert not page.locator('details[open]').count();assert page.locator('#U26').inner_text().find('미적용')>=0;assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path=str(OUT/f'document-rows-{width}.png'))
 browser.close()
assert not errors,errors
assert not missing,missing
(OUT/'browser.json').write_text(json.dumps({'rows':rows,'errors':errors,'missing':missing,'limits':'Practice fixtures use shipped Engine/Scene. No full-campaign traversal or natural acquisition playthrough claimed.'},ensure_ascii=False,indent=2)+'\n')
print('PASS shipped runtime scenes, mobile detail and compact documents; no exceptions/404',flush=True)
